+
+// Stateless uppercase transform (shared by all paths)
+function uppercaseChunk(chunk) {
+  const buf = Buffer.allocUnsafe(chunk.length);
+  for (let i = 0; i < chunk.length; i++) {
+    const b = chunk[i];
+    buf[i] = (b >= 0x61 && b <= 0x7a) ? b - 0x20 : b;
+  }
+  return buf;
+}
