+// ---------------------------------------------------------------------------
+// Classic streams path: createReadStream -> Transform (upper) -> createGzip
+// ---------------------------------------------------------------------------
+async function benchClassic(n, filesize) {
+  await runClassic();
+
+  bench.start();
+  let totalBytes = 0;
+  for (let i = 0; i < n; i++) {
